<?php
require_once __DIR__.'/../includes/auth.php'; require __DIR__.'/../includes/db.php';
$msg='';
if(isset($_GET['create'])){ stock_validate_action_token(); $rid=(int)$_GET['create']; $r=$conn->query("SELECT * FROM rentals WHERE id=$rid LIMIT 1")->fetch_assoc(); if($r){ $ref='NR-'.date('Ymd').'-'.$rid; $notes='Customer did not return the car by the agreed date. Use this internal case record for any external report.'; $user=$_SESSION['user_id']??null; $stmt=$conn->prepare("INSERT INTO not_returned_cases (rental_id,customer_id,car_id,case_reference,notes,created_by) SELECT ?,?,?,?,?,? WHERE NOT EXISTS (SELECT 1 FROM not_returned_cases WHERE rental_id=? AND status IN ('Open','Followed Up','Reported'))"); $stmt->bind_param('iiissii',$rid,$r['customer_id'],$r['cars_id'],$ref,$notes,$user,$rid); $stmt->execute(); $msg='Not-returned case opened.'; } }
if(isset($_GET['resolve'])){ stock_validate_action_token(); $id=(int)$_GET['resolve']; $conn->query("UPDATE not_returned_cases SET status='Resolved',resolved_at=NOW() WHERE id=$id"); $msg='Case resolved.'; }
$overdue=$conn->query("SELECT r.id,c.full_name,ca.reg_no,r.end_date FROM rentals r JOIN customers c ON r.customer_id=c.id JOIN cars ca ON r.cars_id=ca.id WHERE r.status='Active' AND r.end_date < CURDATE() ORDER BY r.end_date ASC");
$cases=$conn->query("SELECT n.*,c.full_name,ca.reg_no,r.end_date FROM not_returned_cases n LEFT JOIN customers c ON n.customer_id=c.id LEFT JOIN cars ca ON n.car_id=ca.id LEFT JOIN rentals r ON n.rental_id=r.id ORDER BY n.id DESC");
?>
<!DOCTYPE html><html><head><title><?=h(cr_not_returned_title())?></title></head><body><?php include __DIR__.'/../includes/header.php'; include __DIR__.'/../includes/leftsidebar.php';?><div class="content-page"><h2><?=h(cr_not_returned_title())?></h2><p>Internal case log for cars not returned on time.<?php if(cr_setting('authority_report_name')!==''):?> Use the case reference when reporting to <?=h(cr_setting('authority_report_name'))?>.<?php endif;?></p><?php if($msg):?><p class="success-msg"><?=h($msg)?></p><?php endif;?><h3>Overdue Active Rentals</h3><table class="table" border="1" cellpadding="10"><tr><th>Rental</th><th>Customer</th><th>Car</th><th>Due Date</th><th>Action</th></tr><?php if($overdue&&$overdue->num_rows):while($o=$overdue->fetch_assoc()):?><tr><td>#<?=h($o['id'])?></td><td><?=h($o['full_name'])?></td><td><?=h($o['reg_no'])?></td><td><?= h(cr_date($o['end_date'])) ?></td><td><a class="btn btn-danger" href="<?=h(stock_action_url('?create=' . (int)$o['id']))?>">Open Case</a></td></tr><?php endwhile;else:?><tr><td colspan="5">No overdue active rentals.</td></tr><?php endif;?></table><h3>Cases</h3><table class="table" border="1" cellpadding="10"><tr><th>Ref</th><th>Rental</th><th>Customer</th><th>Car</th><th>Status</th><th>Notes</th><th>Action</th></tr><?php if($cases&&$cases->num_rows):while($c=$cases->fetch_assoc()):?><tr><td><?=h($c['case_reference'])?></td><td>#<?=h($c['rental_id'])?></td><td><?=h($c['full_name'])?></td><td><?=h($c['reg_no'])?></td><td><?=h($c['status'])?></td><td><?=h($c['notes'])?></td><td><?php if(!in_array($c['status'],['Resolved','Closed'])):?><a class="btn btn-success" href="<?=h(stock_action_url('?resolve=' . (int)$c['id']))?>">Resolve</a><?php endif;?></td></tr><?php endwhile;else:?><tr><td colspan="7">No cases yet.</td></tr><?php endif;?></table></div></body></html>
